name: Cloud Dispatch Cleanup
on:
  push:
    branches:
      - main
  pull_request:
    branches:
      - main
  workflow_dispatch:

jobs:
  cleanup:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout Repository
        uses: actions/checkout@v4

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '18'
          cache: 'npm'

      - name: Install Dependencies
        run: npm ci

      - name: Run Cleanup Script
        run: |
          # Create cleanup script
          cat > cleanup.js << 'EOF'
          const fs = require('fs');
          const path = require('path');

          // Remove node_modules directories
          function removeNodeModules(dir) {
            const items = fs.readdirSync(dir);
            for (const item of items) {
              const fullPath = path.join(dir, item);
              if (item === 'node_modules') {
                console.log(`Removing ${fullPath}`);
                try {
                  fs.rmSync(fullPath, { recursive: true });
                } catch (err) {
                  console.error(`Failed to remove ${fullPath}:`, err);
                }
              } else if (fs.statSync(fullPath).isDirectory()) {
                removeNodeModules(fullPath);
              }
            }
          }

          // Remove all node_modules directories
          removeNodeModules('.');

          // Remove package-lock.json if exists
          if (fs.existsSync('package-lock.json')) {
            console.log('Removing package-lock.json');
            fs.unlinkSync('package-lock.json');
          }

          // Remove npm cache
          console.log('Clearing npm cache');
          try {
            require('child_process').execSync('npm cache clean --force');
          } catch (err) {
            console.error('Failed to clear npm cache:', err);
          }

          console.log('Cleanup completed successfully');
          EOF

          # Run cleanup
          node cleanup.js

      - name: Commit Cleanup Changes
        run: |
          git config --local user.email "action@github.com"
          git config --local user.name "GitHub Action"
          git add -A
          if ! git diff-index --quiet HEAD; then
            git commit -m "chore: cleanup build artifacts and dependencies" || echo "No changes to commit"
          fi

      - name: Push Changes
        uses: ad-m/github-push-action@master
        with:
          github_token: ${{ secrets.GITHUB_TOKEN }}
          branch: ${{ github.ref }}
